      "subtitle": "Опиши цель — попробуем подобрать технику Кехо за 3 сообщения"
    },
    "price": {
      "trial_text": "Тест и демо-чат — бесплатно",
      "price_text": "Полный доступ — дешевле одной коуч-сессии",
      "anchor_text": "Подробнее о тарифах"
    },
    "main_concepts": [
      "Визуализация",
      "Аффирмации",
      "Закладка чувств",
      "Альбом побед",
      "Лаборатория возможностей",
      "Сознание изобилия"
    ]
  }'::jsonb,

  -- ═══ anonymous_quick_replies ═══
  '[
    {"text": "Хочу финансовой свободы — с чего начать?", "type": "normal"},
    {"text": "У меня застряло убеждение — как переписать?", "type": "normal"},
    {"text": "Расскажи про визуализацию с нуля", "type": "normal"},
    {"text": "Мне сложно сформулировать", "type": "exit"}
  ]'::jsonb,

  -- ═══ hub_messages (3 обязательных ключа) ═══
  '{
    "first": "Привет. Это твой тренажёр по «Подсознанию может всё» Джона Кехо — 5 рабочих техник без эзотерики. Начни с теста — <strong>~7 минут, 25 вопросов</strong>. По результатам я подскажу, какие 2 техники сейчас твоя зона роста.",
    "returning_test": "С возвращением. По твоему профилю самые сильные темы — <strong>{theme1}</strong> и <strong>{theme2}</strong>. С чего начнём сегодня?",
    "returning_notest": "С возвращением. Если ещё не проходил тест — пройди, и я подскажу с какой техники Кехо тебе стартовать. А пока выбирай инструмент."
  }'::jsonb
);

-- ═══ Верификация ═══
SELECT
  slug, title,
  features->>'free_chat' as free_chat,
  features->>'author_chat' as author_chat,
  features->>'portrait' as portrait,
  features->>'test' as test,
  features->>'themes' as themes,
  (system_prompt IS NOT NULL) as has_sp,
  (author_chat_system_prompt IS NOT NULL) as has_acsp,
  (anonymous_system_prompt IS NOT NULL) as has_asp,
  (portrait_prompt IS NOT NULL) as has_pp,
  (landing_data IS NOT NULL) as has_landing,
  (hub_messages IS NOT NULL) as has_hub,
  landing_data->'author'->>'photo_url' as photo_url,
  landing_data->'book'->>'cover_url' as cover_url,
  jsonb_array_length(landing_data->'main_concepts') as main_concepts_count
FROM programs
WHERE slug = 'mind-power';
